import 'package:flutter/widgets.dart';

/// Single source of truth for every color, type style, spacing, radius, and
/// elevation value used anywhere in the app (Constitution Principle IV; RNF08).
/// Transcribed verbatim from docs/input/prototype/prototype-extract.md §3.
class DesignTokens {
  const DesignTokens._();

  // Colors
  static const Color colorPrimary = Color(0xFF1F3D34);
  static const Color colorPrimaryPressed = Color(0xFF16281F);
  static const Color colorOnPrimary = Color(0xFFF5F1E8);
  static const Color colorAccent = Color(0xFFC98A3E);
  static const Color colorOnAccent = Color(0xFF241C0D);
  static const Color colorSecondary = Color(0xFF7C8B6F);
  static const Color colorSurfaceBg = Color(0xFFF2EFE7);
  static const Color colorSurfaceElevated = Color(0xFFFBF9F4);
  static const Color colorBorder = Color(0xFFE1DACB);
  static const Color colorTextPrimary = Color(0xFF241F19);
  static const Color colorTextSecondary = Color(0xFF6B6255);
  static const Color colorError = Color(0xFFB3402A);
  static const Color colorSuccess = Color(0xFF4C6B4F);
  static const Color colorWarningSync = Color(0xFFC98A3E);
  static const Color colorInfoOffline = Color(0xFF5C7A93);
  static const Color colorChatBubbleUser = Color(0xFFD9DFD3);

  // Typography
  static const String _fontFraunces = 'Fraunces';
  static const String _fontKarla = 'Karla';
  static const String _fontMono = 'IBM Plex Mono';

  static const TextStyle textDisplayLg = TextStyle(
    fontFamily: _fontFraunces,
    fontWeight: FontWeight.w600,
    fontSize: 32,
    height: 38 / 32,
    color: colorTextPrimary,
  );

  static const TextStyle textHeadlineMd = TextStyle(
    fontFamily: _fontFraunces,
    fontWeight: FontWeight.w600,
    fontSize: 24,
    height: 30 / 24,
    color: colorTextPrimary,
  );

  static const TextStyle textTitleLg = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w700,
    fontSize: 20,
    height: 26 / 20,
    color: colorTextPrimary,
  );

  static const TextStyle textTitleSm = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w700,
    fontSize: 16,
    height: 22 / 16,
    color: colorTextPrimary,
  );

  static const TextStyle textBodyLg = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w400,
    fontSize: 16,
    height: 24 / 16,
    color: colorTextPrimary,
  );

  static const TextStyle textBodyMd = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w400,
    fontSize: 14,
    height: 20 / 14,
    color: colorTextPrimary,
  );

  static const TextStyle textLabelMd = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w500,
    fontSize: 13,
    height: 18 / 13,
    color: colorTextPrimary,
  );

  static const TextStyle textMonoCaption = TextStyle(
    fontFamily: _fontMono,
    fontWeight: FontWeight.w500,
    fontSize: 12,
    height: 16 / 12,
    letterSpacing: 0.2,
    color: colorTextPrimary,
  );

  // Spacing (4 dp grid)
  static const double spacingXs = 4;
  static const double spacingSm = 8;
  static const double spacingMd = 16;
  static const double spacingLg = 24;
  static const double spacingXl = 32;
  static const double spacing2xl = 48;

  // Radii
  static const double radiusSm = 8;
  static const double radiusMd = 16;
  static const double radiusLg = 24;
  static const double radiusFull = 999;

  // Sizes
  static const double sizeLoadingDot = 8;
  static const double sizeLoadingIndicator = 20;
  static const double strokeWidthLoadingIndicator = 2;
  static const double dividerThickness = 1;
  static const double borderWidthFocused = 1.5;
  static const double sizeKeypadTapTarget = 56;
  static const double sizeProgressDot = 10;
  static const double sizeBiometricIconContainer = 96;
  static const double sizeBiometricIcon = 44;
  static const double sizeAudioRecordButton = 72;
  static const double sizeAudioRecordIcon = 30;
  static const double sizePhotoTileIcon = 26;
  static const double sizePhotoThumbnail = 64;
  static const double sizeStatusIcon = 32;

  // Elevation
  static const List<BoxShadow> elevation1 = [
    BoxShadow(
      color: Color.fromRGBO(36, 31, 25, 0.08),
      offset: Offset(0, 1),
      blurRadius: 3,
    ),
  ];

  static const List<BoxShadow> elevation2 = [
    BoxShadow(
      color: Color.fromRGBO(36, 31, 25, 0.14),
      offset: Offset(0, 4),
      blurRadius: 16,
    ),
  ];
}

import 'dart:io';

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/domain/repositories/photo_capture_repository.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
import 'package:cerne/features/capture/presentation/widgets/capture_status_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

const _permissionDeniedMessage =
    'Permita o acesso à câmera ou às fotos para continuar.';

/// Two compact tiles, "Câmera" and "Galeria", with no image selected yet,
/// for [InsertionModalFotoCaptura] (FR-005); the permission-denied message;
/// a thumbnail with a spinner for [InsertionModalFotoProcessing]; a
/// thumbnail next to an editable review field for
/// [InsertionModalFotoReconhecido]/[InsertionModalFotoSaveFailure]
/// (FR-006/FR-009); the plain generic loading indicator for
/// [InsertionModalFotoSaving]; and [RecognitionErrorView] with its second
/// action, "Salvar só a foto", for [InsertionModalFotoFailure] (FR-007/
/// FR-008).
class FotoTabView extends StatelessWidget {
  const FotoTabView({required this.state, super.key});

  final InsertionModalState state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<InsertionModalBloc>();
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      child: ConstrainedBox(
        constraints: const BoxConstraints(minHeight: _minTabContentHeight),
        child: Center(
          child: switch (state) {
            InsertionModalFotoCaptura() => _CapturaView(
              onSourceSelected: (source) =>
                  bloc.add(PhotoSourceSelected(source)),
            ),
            InsertionModalFotoPermissionDenied() =>
              const CapturePermissionDeniedMessage(
                message: _permissionDeniedMessage,
              ),
            InsertionModalFotoProcessing(imagePath: final imagePath) =>
              _ProcessingView(imagePath: imagePath),
            InsertionModalFotoReconhecido(
              imagePath: final imagePath,
              text: final text,
            ) =>
              _ReviewView(
                imagePath: imagePath,
                text: text,
                message: null,
                onTextChanged: (value) =>
                    bloc.add(PhotoReviewTextChanged(value)),
                onSave: () => bloc.add(const PhotoSaveConfirmed()),
              ),
            InsertionModalFotoSaveFailure(
              imagePath: final imagePath,
              text: final text,
              message: final message,
            ) =>
              _ReviewView(
                imagePath: imagePath,
                text: text,
                message: message,
                onTextChanged: (value) =>
                    bloc.add(PhotoReviewTextChanged(value)),
                onSave: () => bloc.add(const PhotoSaveConfirmed()),
              ),
            InsertionModalFotoSaving() => const CaptureLoadingIndicator(),
            InsertionModalFotoFailure(
              imagePath: final imagePath,
              message: final message,
            ) =>
              Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  _Thumbnail(imagePath: imagePath),
                  const SizedBox(height: DesignTokens.spacingMd),
                  RecognitionErrorView(
                    message: message,
                    onRetry: () => bloc.add(const RetryRequested()),
                    secondaryAction: (
                      'Salvar só a foto',
                      () => bloc.add(const PhotoSaveWithoutTextRequested()),
                    ),
                  ),
                ],
              ),
            _ => const SizedBox.shrink(),
          },
        ),
      ),
    );
  }
}

class _Thumbnail extends StatelessWidget {
  const _Thumbnail({required this.imagePath});

  final String imagePath;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(DesignTokens.radiusSm),
      child: Image.file(
        File(imagePath),
        width: DesignTokens.sizePhotoThumbnail,
        height: DesignTokens.sizePhotoThumbnail,
        fit: BoxFit.cover,
      ),
    );
  }
}

class _ProcessingView extends StatelessWidget {
  const _ProcessingView({required this.imagePath});

  final String imagePath;

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        _Thumbnail(imagePath: imagePath),
        const SizedBox(height: DesignTokens.spacingMd),
        const CaptureLoadingIndicator(),
        const SizedBox(height: DesignTokens.spacingSm),
        Text('Reconhecendo texto...', style: DesignTokens.textLabelMd),
      ],
    );
  }
}

class _ReviewView extends StatelessWidget {
  const _ReviewView({
    required this.imagePath,
    required this.text,
    required this.message,
    required this.onTextChanged,
    required this.onSave,
  });

  final String imagePath;
  final String text;
  final String? message;
  final ValueChanged<String> onTextChanged;
  final VoidCallback onSave;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _Thumbnail(imagePath: imagePath),
            const SizedBox(width: DesignTokens.spacingMd),
            Expanded(
              child: TextFormField(
                key: const ValueKey('photoReviewField'),
                initialValue: text,
                maxLines: 6,
                minLines: 3,
                onChanged: onTextChanged,
              ),
            ),
          ],
        ),
        if (message != null) ...[
          const SizedBox(height: DesignTokens.spacingSm),
          Text(
            message!,
            style: DesignTokens.textBodyMd.copyWith(
              color: DesignTokens.colorError,
            ),
          ),
        ],
        const SizedBox(height: DesignTokens.spacingMd),
        ElevatedButton(
          onPressed: text.trim().isNotEmpty ? onSave : null,
          child: const Text('Salvar'),
        ),
      ],
    );
  }
}

const _minTabContentHeight = 200.0;

class _CapturaView extends StatelessWidget {
  const _CapturaView({required this.onSourceSelected});

  final ValueChanged<PhotoSource> onSourceSelected;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        _PhotoSourceTile(
          icon: Icons.camera_alt_outlined,
          label: 'Câmera',
          onTap: () => onSourceSelected(PhotoSource.camera),
        ),
        const SizedBox(width: 12),
        _PhotoSourceTile(
          icon: Icons.photo_library_outlined,
          label: 'Galeria',
          onTap: () => onSourceSelected(PhotoSource.gallery),
        ),
      ],
    );
  }
}

class _PhotoSourceTile extends StatelessWidget {
  const _PhotoSourceTile({
    required this.icon,
    required this.label,
    required this.onTap,
  });

  final IconData icon;
  final String label;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(
          horizontal: DesignTokens.spacingLg,
          vertical: DesignTokens.spacingMd,
        ),
        decoration: BoxDecoration(
          color: DesignTokens.colorSurfaceBg,
          borderRadius: BorderRadius.circular(DesignTokens.radiusMd),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              icon,
              size: DesignTokens.sizePhotoTileIcon,
              color: DesignTokens.colorPrimary,
            ),
            const SizedBox(height: DesignTokens.spacingSm),
            Text(label, style: DesignTokens.textLabelMd),
          ],
        ),
      ),
    );
  }
}

